import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static long[] factorial;
    public static void main(String[] args) {
        var scanner = new MyScanner();
        var printer = new PrintWriter(new BufferedOutputStream(System.out));
        int test = 1;
        while (test-- > 0) {
            int n = scanner.nextInt();
            long kk = scanner.nextLong();
            factorial = new long[n + 1];
            factorial[0] = 1L;
            for (int idx = 1; idx <= n; idx++) {
                factorial[idx] = (factorial[idx - 1] * idx) % MOD;
            }
            if (kk == 0) {
                printer.println(factorial[n]);
            } else if (kk >= n) {
                printer.println(0);
            } else {
                int k = (int) kk;
                long sum = 0L;
                int sign = 1;
                int limit = n - k;
                for (int i = limit; i >= 0; i--) {
                    long term = modPow(i, n) * nCr(limit, i) % MOD;
                    sum = (sum + MOD + (term * sign) % MOD) % MOD;
                    sign = -sign;
                }
                long answer = 2L * nCr(n, k) % MOD * sum % MOD;
                printer.println(answer);
            }
        }
        printer.close();
    }
    static long nCr(int n, int m) {
        if (m == 0 || m == n) return 1L;
        if (m > n || m < 0) return 0L;
        long denom = (factorial[m] * factorial[n - m]) % MOD;
        return factorial[n] * modPow(denom, MOD - 2) % MOD;
    }
    static long modPow(long base, long exp) {
        long result = 1L;
        while (exp != 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>>= 1;
        }
        return result;
    }
    static class MyScanner {
        BufferedReader br;
        StringTokenizer st;
        MyScanner() { br = new BufferedReader(new InputStreamReader(System.in)); }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try { st = new StringTokenizer(br.readLine()); }
                catch (IOException e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() {
            String str = "";
            try { str = br.readLine(); } catch (IOException e) { e.printStackTrace(); }
            return str;
        }
    }
}
